export type Item = { sku: string; price: number; qty: number };

export const cart = {
  items: [] as Item[],
  add(item: Item) {
    this.items.push(item);
  },
  sum() {
    return this.items.reduce((s, i) => s + i.price * i.qty, 0);
  },
};

