import { cart } from "./cart.ts";
import { stripe } from "./pay/stripe.ts";

export function Checkout() {
  const total = cart.sum();
  return (
    <Pay total={total}>
      <Card onPay={() => stripe.charge(total * 100)} />
    </Pay>
  );
}

import { cart } from "./cart.ts";
import { stripe } from "./pay/stripe.ts";
import { applePay } from "./pay/apple.ts";

export function Checkout() {
  const total = cart.sum();
  return (
    <Pay total={total}>
      {applePay.available() && <ApplePay onPay={() => applePay.charge(total * 100)} />}
      <Card onPay={() => stripe.charge(total * 100)} />
    </Pay>
  );
}

